    /* #211 wave 2: una infeccion, sepsis */
    ['fever', /fever|fiebre|calentura|dengu|burning up|(?:hot|burning|warm) to the touch|^(?!.*(?:water|agua|freez|fridge|oven|horno|soil|compost|weather|congel|refri|incubat|brood|chick|pollit|engine|motor|batter|bateria)).*(?:\btemp\w*\b.{0,15}\b(?:9\d|10\d|3[789]|4[01])(?:[.,]\d)?\b|\b(?:9\d|10\d|3[789]|4[01])(?:[.,]\d)? ?(?:degrees|grados)? (?:de )?(?:temperatura|fiebre|calentura))|(?:has|have|got|with|think\w* (?:she|he|it|they) (?:has|have)) (?:an |a bad |some )?infection|stiff neck|cuello (?:tieso|rigido|duro)|meningit|(?:tiene|tenga|con|agarro|le dio) (?:una |la )?infeccion|sepsis|septic/, 'Fever / suspected infection', 'Fiebre / posible infección'],
    ['water', /^(?!.*(?:pilot|piloto|smell\w* (?:of )?gas|gas smell|huele a gas|olor a gas|fuga de gas|gas leak|water heater|calentador de agua|boiler|furnace|caldera|water bath|bano maria|canning|canner|\bjars?\b|frasco|envas|conserva|techo|roof|leak|gotera|tarp|\blona\b))(?=.*(?:drink|\bsafe|unsafe|purif|potab|\bboil|hierv|\bclean|limpi|colou?r|brown|yellow|\bcafe\b|amarill|well water|\bpozo|treat|disinfect|steril|chlor|bleach|iodine|filter|filtr|clean water|dirty|contamin|smell|taste|cloudy|murky|tomar|beber|bebi|segur|herv|purific|desinfect|clor|yodo|agua limpia|suci|turbi|huele|sabor|sabe (?:a|raro|feo|mal))).*(?:water\b|\bagua\b)/, 'Is this water safe?', '¿Es segura esta agua?']
