          for (k in qw) { if (it._w[k]) { any = true; } else { all = false; } }
          if (all && any && score < 2.5) { score = 2.5; }        // whole-word match
          if (score === 2 && !any) { score = 0.8; }              // 'well' in 'sewell'
          if (score <= 0) { continue; }
          if (it.h) { score *= 0.5; }                            // historical demote
