        '<div class="l-lb-frame" role="dialog" aria-modal="true">' +
          '<div class="l-lb-head"><span class="ttl"></span>' +
            '<button class="l-lb-close" type="button">✕ ' + (isES() ? 'Cerrar' : 'Close') + '</button></div>' +
          '<div class="l-lb-stage"><img alt="">' +
            '<button class="l-lb-arrow prev" type="button" aria-label="' + (isES() ? 'Foto anterior' : 'Previous photo') + '">‹</button>' +
            '<button class="l-lb-arrow next" type="button" aria-label="' + (isES() ? 'Foto siguiente' : 'Next photo') + '">›</button></div>' +
          '<div class="l-lb-bar"><span class="count"></span><a class="dl" href="#">↓ ' + (isES() ? 'Descargar foto' : 'Download photo') + '</a></div>' +
          '<div class="l-lb-body"></div></div>';
