    wrap.className = 'l-filter' + (inline ? ' l-filter--inline' : '');
    var isMac = /Mac/.test(navigator.platform || '');
    wrap.innerHTML = '<input type="search" placeholder="' +
      (isES() ? (isMac ? '⌃ o ⌘F filtrar' : '⌃F filtrar') : isMac ? '⌃ or ⌘F filter' : '⌃F filter') +
      '" aria-label="' + (isES() ? 'Filtrar esta página' : 'Filter this page') + '"><div class="count"></div>';
    anchor.parent.insertBefore(wrap, anchor.before);
