        var n = gs[g].nextElementSibling, any = false;
        while (n && n.className !== 'l-group') {
          if (n.style && n.style.display !== 'none' && /l-doc-row/.test(n.className)) { any = true; break; }
          n = n.nextElementSibling;
        }
