        var rows = ds[d].querySelectorAll(filterSel), hit = false;
        if (!rows.length) { continue; }
        for (var r = 0; r < rows.length; r++) { if (rows[r].style.display !== 'none') { hit = true; break; } }
        ds[d].style.display = (hit || !q) ? '' : 'none';
        if (q && hit && !ds[d].open) { ds[d].open = true; ds[d].setAttribute('data-fopen', '1'); }
